-- 248: the daily story. Four tables (daily_story_metrics, daily_story_facts, daily_story, daily_story_patterns), one scoreboard view and five analytics views over them.
-- daily_story_facts holds, per Pacific day, the JSON facts (every metric against its same-weekday baseline, the exact decomposition of NC ROAS, mix-versus-rate cuts, the change
-- ledger, per-source sections); daily_story holds the short narrative built from those facts only; daily_story_patterns the change types seen each day with the next 1-3 days'
-- outcomes; the scoreboard ranks 'has preceded' rates with sample sizes. Additive and idempotent. Jobs: etl/daily_story.py (nightly, non-fatal, after Klaviyo).
CREATE TABLE IF NOT EXISTS daily_story_metrics (
  metric_key   text    PRIMARY KEY,
  sort_order   integer NOT NULL,
  metric_group text    NOT NULL,
  label        text    NOT NULL,
  unit         text    NOT NULL,
  basis        text    NOT NULL,
  formula      text    NOT NULL,
  source       text    NOT NULL
);

CREATE TABLE IF NOT EXISTS daily_story_facts (
  day        date        PRIMARY KEY,
  facts      jsonb       NOT NULL,
  version    text        NOT NULL,
  coverage   text        NOT NULL CHECK (coverage IN ('full', 'partial', 'not_ready')),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS daily_story (
  day        date        PRIMARY KEY,
  headline   text        NOT NULL,
  story      text        NOT NULL,
  confidence jsonb       NOT NULL DEFAULT '{}'::jsonb,
  cannot_see jsonb       NOT NULL DEFAULT '[]'::jsonb,
  model      text,
  source     text        NOT NULL DEFAULT 'template' CHECK (source IN ('llm', 'template')),
  note       text        NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS daily_story_patterns (
  day              date             NOT NULL,
  change_type      text             NOT NULL,
  magnitude_bucket text             NOT NULL,
  subject          text             NOT NULL DEFAULT '',
  magnitude        double precision,
  out_days         integer          NOT NULL DEFAULT 0,
  out_nc_roas      double precision,
  out_cpm          double precision,
  out_ctr          double precision,
  out_conv         double precision,
  out_aov          double precision,
  d1_nc_roas       double precision,
  d1_cpm           double precision,
  d1_ctr           double precision,
  d1_conv          double precision,
  d1_aov           double precision,
  updated_at       timestamptz      NOT NULL DEFAULT now(),
  PRIMARY KEY (day, change_type)
);
CREATE INDEX IF NOT EXISTS daily_story_patterns_type ON daily_story_patterns (change_type, magnitude_bucket);

-- scoreboard: how often each change type has preceded a rise / fall (more than 5%) in each outcome over the next 1-3 days against the same weekday's baseline, next to the rate
-- on every day (the base rate), with sample sizes; only rows with n >= 6. Correlation, not cause. Always current: it recomputes from daily_story_patterns on every read.
CREATE OR REPLACE VIEW daily_story_pattern_scoreboard AS
WITH long AS (
  SELECT p.day, p.change_type, p.magnitude_bucket, v.metric, v.delta
  FROM daily_story_patterns p
  CROSS JOIN LATERAL (VALUES ('nc_roas', p.out_nc_roas), ('cpm', p.out_cpm), ('ctr', p.out_ctr), ('conv', p.out_conv), ('aov', p.out_aov)) AS v (metric, delta)
  WHERE p.out_days >= 1 AND v.delta IS NOT NULL
), base AS (
  SELECT metric, count(*) AS n_days, avg((delta > 0.05)::int)::double precision AS base_rise_rate, avg((delta < -0.05)::int)::double precision AS base_fall_rate
  FROM long WHERE change_type = '_all_days' GROUP BY metric
), g AS (
  SELECT change_type, coalesce(magnitude_bucket, '(any size)') AS magnitude_bucket, metric, count(*) AS n,
         count(*) FILTER (WHERE delta > 0.05) AS rises, count(*) FILTER (WHERE delta < -0.05) AS falls,
         (percentile_cont(0.5) WITHIN GROUP (ORDER BY delta))::double precision AS median_delta, avg(delta)::double precision AS mean_delta
  FROM long WHERE change_type <> '_all_days'
  GROUP BY GROUPING SETS ((change_type, magnitude_bucket, metric), (change_type, metric))
)
SELECT g.change_type, g.magnitude_bucket, g.metric, g.n, g.rises, g.falls,
       g.rises::double precision / g.n AS rise_rate, g.falls::double precision / g.n AS fall_rate,
       b.base_rise_rate, b.base_fall_rate,
       g.rises::double precision / g.n - b.base_rise_rate AS rise_lift, g.falls::double precision / g.n - b.base_fall_rate AS fall_lift,
       g.median_delta, g.mean_delta, b.n_days AS base_days, 'correlation, not cause'::text AS label
FROM g JOIN base b USING (metric)
WHERE g.n >= 6;

CREATE SCHEMA IF NOT EXISTS analytics;
CREATE OR REPLACE VIEW analytics.daily_story AS SELECT day, headline, story, confidence, cannot_see, model, source, note, created_at FROM public.daily_story;
CREATE OR REPLACE VIEW analytics.daily_story_facts AS SELECT day, facts, version, coverage, created_at FROM public.daily_story_facts;
CREATE OR REPLACE VIEW analytics.daily_story_patterns AS SELECT day, change_type, magnitude_bucket, subject, magnitude, out_days, out_nc_roas, out_cpm, out_ctr, out_conv, out_aov, d1_nc_roas, d1_cpm, d1_ctr, d1_conv, d1_aov, updated_at FROM public.daily_story_patterns;
CREATE OR REPLACE VIEW analytics.daily_story_pattern_scoreboard AS SELECT * FROM public.daily_story_pattern_scoreboard;
CREATE OR REPLACE VIEW analytics.daily_story_metric_registry AS SELECT metric_key, sort_order, metric_group, label, unit, basis, formula, source FROM public.daily_story_metrics;

-- analytics.catalog and analytics.metric_glossary: regenerated from docs/schema/descriptions.py (new domain 'story', five new glossary entries)
CREATE OR REPLACE VIEW analytics.catalog AS
SELECT c.relname::text AS view_name,
       COALESCE(k.domain, 'unassigned') AS domain,
       COALESCE(k.description, split_part(obj_description(c.oid, 'pg_class'), ' Grain: ', 1)) AS description,
       k.grain,
       k.first_day,
       k.last_day,
       COALESCE(k.row_estimate, (SELECT NULLIF(t.reltuples, -1)::bigint FROM pg_class t WHERE t.oid = to_regclass('public.' || c.relname))) AS row_estimate
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'analytics'
LEFT JOIN (
SELECT 'meta_ads'::text AS view_name, 'marketing'::text AS domain, 'Dimension: one row per Meta ad (every ad the pipeline has ever seen: 42K, most ARCHIVED or DELETED) with its campaign, ad set, product, status and all-time totals. Join to the daily views on ad_id (they already carry the main names).'::text AS description, 'one row per Meta ad_id'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.meta_ads')) AS row_estimate
UNION ALL
SELECT 'meta_ad_daily'::text AS view_name, 'marketing'::text AS domain, 'The main Meta fact view: one row per Meta ad per day with Meta-reported results AND Upstack-attributed new customers / orders side by side, plus the ad''s names, campaign, ad set, stage and product. Roll up from here; never add purchases to Google''s.'::text AS description, 'one row per (day, ad_id)'::text AS grain, (SELECT min(day) FROM public.ad_daily)::date AS first_day, (SELECT max(day) FROM public.ad_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.ad_daily')) AS row_estimate
UNION ALL
SELECT 'meta_adset_daily'::text AS view_name, 'marketing'::text AS domain, 'Ad set x day roll-up of meta_ad_daily (Meta-reported and Upstack bases side by side).'::text AS description, 'one row per (day, adset_id)'::text AS grain, (SELECT min(day) FROM public.ad_daily)::date AS first_day, (SELECT max(day) FROM public.ad_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.ad_daily')) AS row_estimate
UNION ALL
SELECT 'meta_campaign_daily'::text AS view_name, 'marketing'::text AS domain, 'Campaign x day roll-up of meta_ad_daily (Meta-reported and Upstack bases side by side).'::text AS description, 'one row per (day, campaign_id)'::text AS grain, (SELECT min(day) FROM public.ad_daily)::date AS first_day, (SELECT max(day) FROM public.ad_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.ad_daily')) AS row_estimate
UNION ALL
SELECT 'meta_campaign_daily_history'::text AS view_name, 'marketing'::text AS domain, 'Meta campaign x day back to 2024-12-31: the only Meta data before 2026-05-06 (campaign grain, no ad sets or ads). From 2026-05-06 on it equals meta_campaign_daily''s Meta-reported columns.'::text AS description, 'one row per (day, campaign_id) after the day rule (a day is read from ''app'' when it has app rows, else from ''sheet'')'::text AS grain, (SELECT min(day) FROM public.proj_feed_meta_day)::date AS first_day, (SELECT max(day) FROM public.proj_feed_meta_day)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_meta_day')) AS row_estimate
UNION ALL
SELECT 'meta_reach'::text AS view_name, 'marketing'::text AS domain, 'Account-level reach and frequency for Meta (both ad accounts summed). Reach is de-duplicated by Meta per period, so it is stored at each grain and must never be summed across days or weeks.'::text AS description, 'one row per (grain, period_key): grain is ''day'', ''week'' (ISO) or ''month'''::text AS grain, (SELECT min(period_start) FROM public.proj_feed_meta_reach)::date AS first_day, (SELECT max(period_end) FROM public.proj_feed_meta_reach)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_meta_reach')) AS row_estimate
UNION ALL
SELECT 'google_campaign_daily'::text AS view_name, 'marketing'::text AS domain, 'Google Ads campaign x day: Google''s own spend, impressions, clicks and conversions plus Upstack''s attributed new customers / orders. Google has no ad group, ad or keyword grain in this database.'::text AS description, 'one row per (day, campaign_key)'::text AS grain, (SELECT min(day) FROM public.google_daily)::date AS first_day, (SELECT max(day) FROM public.google_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.google_daily')) AS row_estimate
UNION ALL
SELECT 'platform_daily'::text AS view_name, 'marketing'::text AS domain, 'Meta and Google side by side per day. Spend, impressions and clicks are additive across the two platforms; purchases and revenue are not.'::text AS description, 'one row per (day, platform) with platform ''meta'' or ''google'''::text AS grain, (SELECT min(day) FROM public.ad_daily)::date AS first_day, (SELECT max(day) FROM public.ad_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.ad_daily')) AS row_estimate
UNION ALL
SELECT 'orders_daily'::text AS view_name, 'orders'::text AS domain, 'The business''s ACTUAL revenue and customers per Pacific day, counted once (Upstack order-level measures). new_customer_revenue is the numerator of Total NC ROAS.'::text AS description, 'one row per Pacific day with orders'::text AS grain, (SELECT min(day) FROM public.upstack_orders_daily)::date AS first_day, (SELECT max(day) FROM public.upstack_orders_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.upstack_orders_daily')) AS row_estimate
UNION ALL
SELECT 'creative_tracker'::text AS view_name, 'creative'::text AS domain, 'One row per live Creative Tracker row (a concept / ad variant) with its current tag in the product''s own tag set, its hook and its since-launch Meta-reported metrics. The way to ask ''which cluster / ICP / pain point / hook performs''.'::text AS description, 'one row per tracker row (tracker_row_id); an ''ad family'' (family_key) can span several rows'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.tracker_rows')) AS row_estimate
UNION ALL
SELECT 'data_coverage'::text AS view_name, 'pipeline'::text AS domain, 'Freshness and coverage per data source: first and last day held, days, rows, when last loaded. Read it before quoting ''yesterday'' or a trailing window.'::text AS description, 'one row per source'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'etl_runs'::text AS view_name, 'pipeline'::text AS domain, 'Log of every pipeline job run (tracker sync, Meta pull, lifetime pull, status refresh, metrics build, Upstack pull, hook / tag loads). Check it when a number looks stale.'::text AS description, 'one row per job run'::text AS grain, (SELECT min(started_at::date) FROM public.etl_runs)::date AS first_day, (SELECT max(started_at::date) FROM public.etl_runs)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.etl_runs')) AS row_estimate
UNION ALL
SELECT 'meta_breakdown_daily'::text AS view_name, 'marketing'::text AS domain, 'Meta results split by ten everyday breakdowns (audience segment, age, gender, age x gender, country, region, publisher platform, platform position, device platform, hour of day), one row per day x ad x breakdown x value. Meta-reported numbers.'::text AS description, 'one row per (day, account, ad_id, breakdown, value); NO aggregation above ad'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.meta_breakdown_daily')) AS row_estimate
UNION ALL
SELECT 'attribution_source_daily'::text AS view_name, 'attribution'::text AS domain, 'Last-click attribution by ad source (Meta Ads, Google Ads, ...) per Pacific day: new customers and orders each source is credited with, exclusive per order.'::text AS description, 'one row per (day, ad_source)'::text AS grain, (SELECT min(day) FROM public.proj_feed_attribution)::date AS first_day, (SELECT max(day) FROM public.proj_feed_attribution)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_attribution')) AS row_estimate
UNION ALL
SELECT 'attribution_anyclick_daily'::text AS view_name, 'attribution'::text AS domain, 'New customers Upstack credits to Scaling and to Testing Meta campaigns per day under any-click 30-day attribution.'::text AS description, 'one row per (day, stage)'::text AS grain, (SELECT min(day) FROM public.proj_feed_anyclick)::date AS first_day, (SELECT max(day) FROM public.proj_feed_anyclick)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_anyclick')) AS row_estimate
UNION ALL
SELECT 'attribution_unmapped_daily'::text AS view_name, 'attribution'::text AS domain, 'Upstack-credited orders the build could not tie to a Meta ad. They are inside orders_daily and inside no ad-level row of meta_ad_daily.'::text AS description, 'one row per (day, campaign, ad)'::text AS grain, (SELECT min(day) FROM public.upstack_unmapped_daily)::date AS first_day, (SELECT max(day) FROM public.upstack_unmapped_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.upstack_unmapped_daily')) AS row_estimate
UNION ALL
SELECT 'orders_daily_detail'::text AS view_name, 'orders'::text AS domain, 'orders_daily plus the tax collected and the refunds of each Pacific day: the two columns pacing uses to go from gross to net revenue.'::text AS description, 'one row per day'::text AS grain, (SELECT min(day) FROM public.proj_feed_orders)::date AS first_day, (SELECT max(day) FROM public.proj_feed_orders)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_orders')) AS row_estimate
UNION ALL
SELECT 'orders_by_product_daily'::text AS view_name, 'orders'::text AS domain, 'ACTUAL Shopify first-order revenue and new customers per Pacific day by the order''s largest product line (not Meta-attributed): the only product split of actual new-customer revenue.'::text AS description, 'one row per (day, product)'::text AS grain, (SELECT min(day) FROM public.proj_feed_nc_product)::date AS first_day, (SELECT max(day) FROM public.proj_feed_nc_product)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_nc_product')) AS row_estimate
UNION ALL
SELECT 'orders_hourly'::text AS view_name, 'orders'::text AS domain, 'Actual new-customer revenue and first orders by Pacific day and clock hour: the share curve behind the ''NC revenue today'' card.'::text AS description, 'one row per (day, hour) with at least one first order'::text AS grain, (SELECT min(day) FROM public.proj_feed_nc_hourly)::date AS first_day, (SELECT max(day) FROM public.proj_feed_nc_hourly)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_nc_hourly')) AS row_estimate
UNION ALL
SELECT 'amazon_daily'::text AS view_name, 'orders'::text AS domain, 'Amazon.com + B2B sales and Amazon Ads (de-duplicated across v1 / v2 / v3 report generations) by purchase day.'::text AS description, 'one row per day'::text AS grain, (SELECT min(day) FROM public.proj_feed_amazon)::date AS first_day, (SELECT max(day) FROM public.proj_feed_amazon)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_amazon')) AS row_estimate
UNION ALL
SELECT 'site_traffic_daily'::text AS view_name, 'orders'::text AS domain, 'Pixel-tracked visitors, new visitors and sessions per day (Upstack).'::text AS description, 'one row per day'::text AS grain, (SELECT min(day) FROM public.proj_feed_traffic)::date AS first_day, (SELECT max(day) FROM public.proj_feed_traffic)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_traffic')) AS row_estimate
UNION ALL
SELECT 'platform_daily_history'::text AS view_name, 'marketing'::text AS domain, 'Meta and Google spend and platform-reported conversions per day from 2025-01-01 (Upstack ad-platform feed): the longest spend history in the database.'::text AS description, 'one row per (day, platform)'::text AS grain, (SELECT min(day) FROM public.proj_feed_platform)::date AS first_day, (SELECT max(day) FROM public.proj_feed_platform)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_platform')) AS row_estimate
UNION ALL
SELECT 'meta_product_daily'::text AS view_name, 'marketing'::text AS domain, 'Meta spend and link clicks per day by product, classified campaign name -> ad set name -> ad name -> Other.'::text AS description, 'one row per (day, product) after the day rule'::text AS grain, (SELECT min(day) FROM public.proj_feed_meta_product)::date AS first_day, (SELECT max(day) FROM public.proj_feed_meta_product)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_meta_product')) AS row_estimate
UNION ALL
SELECT 'meta_product_reach'::text AS view_name, 'marketing'::text AS domain, 'Unique outbound clicks per product, de-duplicated across the product''s ad sets, at day / week / month grain: the only per-product reach-like metric.'::text AS description, 'one row per (grain, period_key, product)'::text AS grain, (SELECT min(period_start) FROM public.proj_feed_product_reach)::date AS first_day, (SELECT max(period_end) FROM public.proj_feed_product_reach)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_product_reach')) AS row_estimate
UNION ALL
SELECT 'meta_bids_daily'::text AS view_name, 'marketing'::text AS domain, 'Meta bid settings per day, summed: spend on cost-cap / bid-cap ad sets and on ROAS-floor ad sets, with the spend-weighted bid sums.'::text AS description, 'one row per day'::text AS grain, (SELECT min(day) FROM public.proj_feed_bids)::date AS first_day, (SELECT max(day) FROM public.proj_feed_bids)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_bids')) AS row_estimate
UNION ALL
SELECT 'pacing_live_today'::text AS view_name, 'pacing'::text AS domain, 'Today''s Meta spend, Google spend, new-customer revenue and new customers so far, one snapshot per hourly pull from Upstack.'::text AS description, 'one row per pull (pulled_at, to the minute)'::text AS grain, (SELECT min(day) FROM public.proj_live_today_snapshots)::date AS first_day, (SELECT max(day) FROM public.proj_live_today_snapshots)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_live_today_snapshots')) AS row_estimate
