SELECT 'pacing_hourly_spend_curve'::text AS view_name, 'pacing'::text AS domain, 'Meta time-of-day spend curve (the last 30 days'' hourly spend): the typed input behind the intraday projection.'::text AS description, 'one row per hour of day (Pacific)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_pacing_hourly')) AS row_estimate
UNION ALL
SELECT 'pacing_levers'::text AS view_name, 'pacing'::text AS domain, 'The ratios and estimates the pacing page applies (for example the overseas-warehouse units ratio), one row per lever.'::text AS description, 'one row per lever'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_levers')) AS row_estimate
UNION ALL
SELECT 'pacing_meta_spend_monthly'::text AS view_name, 'pacing'::text AS domain, 'Monthly Meta spend from ad_daily, read by the projection drivers module.'::text AS description, 'one row per month'::text AS grain, (SELECT min(day) FROM public.ad_daily)::date AS first_day, (SELECT max(day) FROM public.ad_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.ad_daily')) AS row_estimate
