SELECT 'pipeline_feeds'::text AS view_name, 'pipeline'::text AS domain, 'One row per pacing feed: its mode (sheet / shadow / direct), what was last loaded and through which day.'::text AS description, 'one row per feed'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_runs')) AS row_estimate
