SELECT 'pipeline_feed_verify'::text AS view_name, 'pipeline'::text AS domain, 'Latest verification result per feed and day: the direct pull compared with the sheet-fed table.'::text AS description, 'one row per (feed, day)'::text AS grain, (SELECT min(day) FROM public.proj_feed_verify)::date AS first_day, (SELECT max(day) FROM public.proj_feed_verify)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_feed_verify')) AS row_estimate
UNION ALL
SELECT 'pipeline_refresh_runs'::text AS view_name, 'pipeline'::text AS domain, 'One row per projection module per run of the nightly projection refresh.'::text AS description, 'one row per module run'::text AS grain, (SELECT min(started_at::date) FROM public.proj_refresh_runs)::date AS first_day, (SELECT max(started_at::date) FROM public.proj_refresh_runs)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.proj_refresh_runs')) AS row_estimate
UNION ALL
SELECT 'pipeline_alerts'::text AS view_name, 'pipeline'::text AS domain, 'The hourly health checks that fired: when each problem opened, was last seen, was last alerted and whether it resolved.'::text AS description, 'one row per check id'::text AS grain, (SELECT min(first_seen::date) FROM public.alert_state)::date AS first_day, (SELECT max(last_seen::date) FROM public.alert_state)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.alert_state')) AS row_estimate
